<?php require 'config.php';require_admin();verify_csrf();$a=read_json('services.json',[]);if($_SERVER['REQUEST_METHOD']==='POST'){ $a[]=['id'=>uid('S'),'name'=>trim($_POST['name']),'description'=>trim($_POST['description']),'price'=>(float)$_POST['price'],'image'=>trim($_POST['image']),'active'=>true];write_json('services.json',$a);redirect('services.php');}$title='خدمات التعديل';require 'header.php';?><div class="form"><h1>إضافة خدمة تعديل</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input name="name" placeholder="اسم الخدمة" required><textarea name="description" placeholder="الوصف"></textarea><input type="number" name="price" placeholder="السعر"><input name="image" placeholder="مسار الصورة"><button class="btn">إضافة</button></form></div><br><div class="grid"><?php foreach($a as $s):?><div class="card"><h3><?=e($s['name'])?></h3><p><?=e($s['description'])?></p><div class="price"><?=money((float)$s['price'])?></div></div><?php endforeach;?></div><?php require 'footer.php';?>